1→"""Structural / identity / retained-closure admission of one exported graph.

Full semantic evaluator replay is outside this bounded review.
"""
from __future__ import annotations

import hashlib
import re
import struct
10→from typing import Any

from canonical import (
    AdmissionError,
    admit_json_bytes,
    capability_manifest_id,
    encode_c,
    encode_cve1,
    h_identity,
    parse_h_frame,
20→    sha256_hex,
)
from kit import DOMAIN_TO_PREFIX, PREFIX_TO_DOMAIN, Kit
from schema_validate import HEX64, SHA256_TEXT, TYPED_ID, SchemaBundle, check_order, merge_ref, resolve_pointer
from store import Store

PROOF_INPUT_FORBIDDEN = {"run", "semantic-evidence", "evaluation-seal", "proof-bundle"}
FINDING_EVIDENCE_DOMAINS = {"fact", "coverage", "import", "predicate-witness", "blob"}
INVENTORY_RELATIONS = {"file", "package", "vcs-change"}
SEMANTIC_RELATIONS = {"imports", "references", "calls", "types", "reachability", "unresolved-edge"}
30→CODE_SYNTAX_RELATIONS = {"declares", "literal", "control-flow"}
BODY_LANG_ENUM = {"typescript", "javascript", "rust"}
CODE_LANGUAGES = {"typescript", "javascript", "rust"}
DATA_LANGUAGES = {"json", "toml", "markdown", "yaml"}


class Law:
    def __init__(self, law_id: str, citation: str, description: str):
        self.id = law_id
        self.citation = citation
40→        self.description = description
        self.status = "notReached"  # notReached | executed-pass | executed-fail | diagnostic
        self.detail: dict | None = None


class Admit:
    def __init__(self, kit: Kit, schemas: SchemaBundle, store: Store, graph_name: str):
        self.kit = kit
        self.schemas = schemas
        self.store = store
50→        self.graph_name = graph_name
        self.laws: dict[str, Law] = {}
        self.first_refusal: dict | None = None
        self.diagnostics: list[dict] = []
        self.admitted: dict[tuple[str, str], Any] = {}  # (kind, digest) -> parsed
        self.frames: dict[str, tuple[str, Any]] = {}  # digest -> (domain, record)
        self.canonical_records: dict[str, Any] = {}
        self.raw_artifacts: dict[str, bytes] = {}
        self.reached_typed: set[str] = set()
        self.run: dict | None = None
60→        self.plan: dict | None = None
        self.snapshot: dict | None = None
        self.inventory_by_path: dict[str, dict] = {}
        self.closures: dict[str, dict] = {}
        self.native_contexts: dict[str, tuple[str, dict]] = {}  # hex -> (domain, rec)
        self.native_universes: dict[str, tuple[str, dict]] = {}
        self.facts: dict[str, dict] = {}
        self.scopes: dict[str, dict] = {}
        self.coverages: dict[str, dict] = {}
        self.views: dict[str, dict] = {}
70→        self.imports: dict[str, dict] = {}
        self.proof: dict | None = None
        self.evidence: dict | None = None
        self.seal: dict | None = None
        self.analysis_spec: dict | None = None
        self.config: dict | None = None
        self.exec_plan: dict | None = None
        self.execution_inputs: dict | None = None
        self.policy: dict | None = None
        self.rule_program: dict | None = None
80→        self.cap_bytes: bytes | None = None
        self.replay_result: dict | str = "UNEXECUTED"

    def law(self, law_id: str, citation: str, description: str) -> Law:
        if law_id not in self.laws:
            self.laws[law_id] = Law(law_id, citation, description)
        return self.laws[law_id]

    def mark_pass(self, law_id: str, citation: str, description: str, detail: dict | None = None) -> None:
        law = self.law(law_id, citation, description)
90→        if self.first_refusal is not None:
            if law.status == "notReached":
                law.status = "diagnostic"
            return
        if law.status == "notReached":
            law.status = "executed-pass"
            law.detail = detail

    def refuse(self, law_id: str, code: str, message: str, citation: str, operands: dict) -> None:
        law = self.law(law_id, citation, message)
100→        rec = {
            "lawId": law_id,
            "code": code,
            "message": message,
            "citation": citation,
            "operands": operands,
        }
        if self.first_refusal is None:
            self.first_refusal = rec
            law.status = "executed-fail"
110→            law.detail = rec
        else:
            rec["role"] = "diagnostic"
            self.diagnostics.append(rec)
            law.status = "diagnostic"
            law.detail = rec
        raise AdmissionError(code, message, citation, operands)

    def catch(self, law_id: str, citation: str, description: str, fn):
        try:
120→            fn()
            self.mark_pass(law_id, citation, description)
        except AdmissionError as e:
            if self.first_refusal is None:
                self.refuse(law_id, e.code, e.message, e.citation or citation, e.operands)
            else:
                self.diagnostics.append(
                    {"lawId": law_id, "code": e.code, "message": e.message, "citation": e.citation, "operands": e.operands, "role": "diagnostic"}
                )
                self.law(law_id, citation, description).status = "diagnostic"
130→
    def run_admission(self) -> dict:
        try:
            self._phase_store()
            self._phase_run_root()
            self._phase_graph()
            self._phase_native()
            self._phase_relations()
            self._phase_coverage()
            self._phase_citations()
140→            self._phase_closures()
            self._phase_capability()
            self._phase_component()
            self._phase_execution_inputs()
            self._phase_joins()
            self.structural_ok = self.first_refusal is None
            self._phase_replay()
        except AdmissionError as e:
            if self.first_refusal is None:
                self.first_refusal = {
150→                    "lawId": "UNCAUGHT_ADMISSION_ERROR",
                    "code": e.code,
                    "message": e.message,
                    "citation": e.citation,
                    "operands": e.operands,
                }
                law = self.law("UNCAUGHT_ADMISSION_ERROR", e.citation, e.message)
                law.status = "executed-fail"
                law.detail = self.first_refusal
        except Exception as e:
160→            import traceback
            if self.first_refusal is None:
                self.first_refusal = {
                    "lawId": "CHECKER_FAULT",
                    "code": "CHECKER_FAULT",
                    "message": f"{type(e).__name__}: {e}",
                    "citation": "checker implementation (not a kit law)",
                    "operands": {"traceback": traceback.format_exc()},
                }
        structural_ok = getattr(self, "structural_ok", self.first_refusal is None and getattr(self, "replay_result", "UNEXECUTED") == "UNEXECUTED")
170→        # If replay refused, first_refusal is the semantic mismatch; structural_ok was captured before replay.
        if not hasattr(self, "structural_ok"):
            self.structural_ok = False
        replay = getattr(self, "replay_result", "UNEXECUTED")
        structural_verdict = "ADMIT" if self.structural_ok else "REFUSE"
        if not self.structural_ok:
            overall = "REFUSE"
        elif isinstance(replay, dict) and replay.get("status") == "REPLAY_MATCH":
            overall = "ADMIT"
        elif isinstance(replay, dict) and replay.get("status") == "REPLAY_REFUSE":
180→            overall = "SEMANTIC_REFUSE"
        else:
            overall = "INCOMPLETE"
        return {
            "graph": self.graph_name,
            "claimedRunId": self.store.claimed_run_id,
            "storeSha256": self.store.file_sha256,
            "storeBytes": self.store.file_bytes,
            "verdict": overall,
            "structuralVerdict": structural_verdict,
190→            "firstRefusal": self.first_refusal,
            "structuralFirstRefusal": None if self.structural_ok else self.first_refusal,
            "diagnostics": self.diagnostics,
            "laws": {
                lid: {
                    "citation": law.citation,
                    "description": law.description,
                    "status": law.status,
                    "detail": law.detail,
                }
200→                for lid, law in self.laws.items()

1→"""Load an exported store. objectTable metadata is a CLAIM; blobs are the bytes."""
from __future__ import annotations

import base64
import json
from pathlib import Path
from typing import Any

from canonical import AdmissionError, sha256_hex
10→

class Store:
    def __init__(self, path: Path, claimed_run_id: str):
        self.path = path
        self.claimed_run_id = claimed_run_id
        raw = path.read_bytes()
        self.file_sha256 = sha256_hex(raw)
        self.file_bytes = len(raw)
        try:
20→            data = json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as e:
            raise AdmissionError(
                "STORE_NOT_JSON",
                "export store is not UTF-8 JSON",
                "export-manifest.json",
                {"path": str(path), "error": str(e)},
            )
        if not isinstance(data, dict):
            raise AdmissionError("STORE_SHAPE", "store root is not an object", "export-manifest.json", {})
30→        self.data = data
        self.object_table: dict[str, Any] = data.get("objectTable") or {}
        self.blobs_b64: dict[str, str] = data.get("blobs") or {}
        self.claimed_blob_count = data.get("blobCount")
        self.blobs: dict[str, bytes] = {}
        self.blob_rehash_errors: list[dict] = []

    def rehash_all_blobs(self) -> list[dict]:
        errors = []
        if not isinstance(self.blobs_b64, dict):
40→            raise AdmissionError("STORE_BLOBS_SHAPE", "blobs is not an object", "identity-and-evidence.md§3 retention", {})
        if self.claimed_blob_count is not None and self.claimed_blob_count != len(self.blobs_b64):
            errors.append(
                {
                    "code": "BLOBCOUNT_MISMATCH",
                    "citation": "export store blobCount claim",
                    "operands": {"claimed": self.claimed_blob_count, "actual": len(self.blobs_b64)},
                }
            )
        for key, b64 in self.blobs_b64.items():
50→            if not isinstance(b64, str):
                errors.append({"code": "BLOB_NOT_B64", "citation": "identity-and-evidence.md§3", "operands": {"key": key}})
                continue
            try:
                raw = base64.b64decode(b64, validate=True)
            except Exception as e:
                errors.append({"code": "BLOB_B64_DECODE", "citation": "identity-and-evidence.md§3", "operands": {"key": key, "error": str(e)}})
                continue
            actual = sha256_hex(raw)
            if actual != key:
60→                errors.append(
                    {
                        "code": "BLOB_REHASH_MISMATCH",
                        "citation": "identity-and-evidence.md§3 (raw SHA256 of exact retained bytes)",
                        "operands": {"claimedKey": key, "actualSha256": actual, "byteLength": len(raw)},
                    }
                )
                continue
            self.blobs[key] = raw
        self.blob_rehash_errors = errors
70→        return errors

    def get_blob(self, digest: str) -> bytes | None:
        if digest in self.blobs:
            return self.blobs[digest]
        return None

    def require_blob(self, digest: str, citation: str, field: str) -> bytes:
        raw = self.get_blob(digest)
        if raw is None:
80→            raise AdmissionError(
                "PREIMAGE_MISSING",
                "retention mode preimage: bytes not retained under this digest",
                citation,
                {"digest": digest, "field": field},
            )
        if sha256_hex(raw) != digest:
            raise AdmissionError(
                "PREIMAGE_REHASH",
                "retained bytes do not rehash to the digest that named them",
90→                citation,
                {"digest": digest, "actual": sha256_hex(raw), "field": field},
            )
        return raw

    def claimed_run_digest(self) -> str:
        rid = self.claimed_run_id
        if ":" in rid:
            prefix, hexpart = rid.split(":", 1)
            if prefix != "run3":
100→                raise AdmissionError(
                    "CLAIMED_RUN_PREFIX",
                    "claimed RunId is not run3",
                    "identity-schemas.v3.json#/x-opensip-evaluator-profile",
                    {"claimedRunId": rid},
                )
            return hexpart
        return rid

